import { mock } from 'bun:test'
const values = new Map<string, string>()
const failedWrites = new Set<string>()
export function failNextStorageWrite(key: string): void { failedWrites.add(key) }
mock.module('expo-secure-store', () => ({
  getItemAsync: async (key: string) => values.get(key) ?? null,
  setItemAsync: async (key: string, value: string) => {
    if (failedWrites.delete(key)) throw new Error('Storage unavailable')
    values.set(key, value)
  },
  deleteItemAsync: async (key: string) => { values.delete(key) },
}))

import { expect, test } from 'bun:test'
import { failNextStorageWrite } from './storage'
import { addMonitor, loadMonitors, monitorMatches, removeMonitor, toggleMonitor } from '../src/engine/monitor/store'

test('failed monitor writes preserve the last saved state and can be retried', async () => {
  const before = await loadMonitors()
  failNextStorageWrite('tru.monitors.v1')
  await expect(addMonitor('Storage rollback fixture')).rejects.toThrow('Storage unavailable')
  expect(await loadMonitors()).toEqual(before)

  const saved = await addMonitor('Storage rollback fixture')
  const monitor = saved.find((item) => item.query === 'Storage rollback fixture')!
  expect(monitor.enabled).toBe(true)
  failNextStorageWrite('tru.monitors.v1')
  await expect(toggleMonitor(monitor.id)).rejects.toThrow('Storage unavailable')
  expect((await loadMonitors()).find((item) => item.id === monitor.id)?.enabled).toBe(true)
  await removeMonitor(monitor.id)
})

test('saved topic monitors match whole words and respect all terms and disabled rules', async () => {
  const saved = await addMonitor('AI research')
  const monitor = saved.find((item) => item.query === 'AI research')!
  try {
    expect(monitorMatches('New AI-powered research tools', [monitor])).toEqual([monitor])
    expect(monitorMatches('Chair research reaches Hawaii', [monitor])).toEqual([])
    expect(monitorMatches('New AI tools', [monitor])).toEqual([])
    const disabled = (await toggleMonitor(monitor.id)).find((item) => item.id === monitor.id)!
    expect(monitorMatches('AI research', [disabled])).toEqual([])
    expect(monitorMatches('CAFÉ opens downtown', [{ ...monitor, query: 'café' }])).toHaveLength(1)
    expect(monitorMatches('New C++ research', [{ ...monitor, query: 'C++' }])).toHaveLength(1)
    expect(monitorMatches('Any headline', [{ ...monitor, query: '  ' }])).toEqual([])
  } finally { await removeMonitor(monitor.id) }
})

import { useEffect, useMemo, useState, type JSX } from 'react'
import { ActivityIndicator, StyleSheet, TextInput, View } from 'react-native'
import { router, useLocalSearchParams } from 'expo-router'
import { SafeAreaView } from 'react-native-safe-area-context'
import * as SecureStore from 'expo-secure-store'
import Ionicons from '@expo/vector-icons/Ionicons'

import { createXPost } from '@/engine/x/client'
import { isGeneralAudienceSocialText } from '@/engine/news/safety'
import { useXSession } from '@/engine/x/session'
import { Button, Text } from '@/ui/design'
import { useHideTabBar } from '@/ui/navigation/useHideTabBar'
import { useKeyboardInset } from '@/ui/navigation/useKeyboardInset'
import { AppHeader } from '@/ui/shell/AppHeader'
import { useTheme, useThemedStyles, type ThemeTokens } from '@/ui/theme'

const MAX_POST_LENGTH = 280

export default function XComposeScreen(): JSX.Element {
  const t = useTheme()
  useHideTabBar()
  const styles = useThemedStyles(makeStyles)
  const session = useXSession()
  const { replyTo, quoteId, quoteUsername, prompt } = useLocalSearchParams<{ replyTo?: string; quoteId?: string; quoteUsername?: string; prompt?: string }>()
  const draftKey = useMemo(() => `tru.x.draft.v1.${replyTo ? `reply.${replyTo}` : quoteId ? `quote.${quoteId}` : 'new'}`, [quoteId, replyTo])
  const [text, setText] = useState('')
  const [hydrated, setHydrated] = useState(false)
  const [sending, setSending] = useState(false)
  const [status, setStatus] = useState<string | null>(null)
  const keyboardInset = useKeyboardInset(52)
  const audienceSafe = !text.trim() || isGeneralAudienceSocialText(text)
  const valid = text.trim().length > 0 && text.length <= MAX_POST_LENGTH && audienceSafe

  useEffect(() => {
    let live = true
    void SecureStore.getItemAsync(draftKey).then((draft) => {
      if (live && draft) setText(draft.slice(0, MAX_POST_LENGTH))
    }).finally(() => { if (live) setHydrated(true) })
    return () => { live = false }
  }, [draftKey])

  useEffect(() => {
    if (!hydrated) return
    const timer = setTimeout(() => {
      if (text) void SecureStore.setItemAsync(draftKey, text)
      else void SecureStore.deleteItemAsync(draftKey)
    }, 300)
    return () => clearTimeout(timer)
  }, [draftKey, hydrated, text])

  const send = async () => {
    if (!valid || sending) return
    setSending(true)
    setStatus(null)
    try {
      const result = await createXPost(text, { replyToId: replyTo, quoteId, quoteUsername })
      if (result.ok) {
        await SecureStore.deleteItemAsync(draftKey)
        router.back()
      } else {
        setStatus(result.message ?? 'X did not accept the post. Check the account and try again.')
      }
    } catch (error) {
      setStatus(error instanceof Error ? error.message : 'Post failed.')
    } finally {
      setSending(false)
    }
  }

  const context = replyTo ? 'Replying in a thread' : quoteId ? `Quoting @${quoteUsername || 'account'}` : null
  return (
    <SafeAreaView style={styles.screen} edges={['top', 'left', 'right']}>
      <AppHeader
        title={replyTo ? 'Reply' : quoteId ? 'Quote post' : 'New post'}
        subtitle={prompt ?? (hydrated ? 'Drafts save on this device' : 'Loading draft')}
        right={sending ? <View style={styles.busy}><ActivityIndicator size="small" color={t.accent} /></View> : <Button compact variant="primary" label="Post" disabled={!valid} onPress={() => void send()} />}
      />
      <View style={[styles.flex, keyboardInset ? { paddingBottom: keyboardInset } : null]}>
        {context ? (
          <View style={styles.context}>
            <Ionicons name={replyTo ? 'return-down-forward-outline' : 'chatbox-ellipses-outline'} size={17} color={t.textMuted} />
            <Text variant="metadata" tone="muted" numberOfLines={1}>{context}</Text>
          </View>
        ) : null}
        <View style={styles.editor}>
          <View style={styles.identity} accessibilityLabel={`Posting as @${session?.username ?? 'connected account'}`}>
            <Text variant="label" weight="900" style={styles.identityText}>{(session?.username?.[0] || 'X').toUpperCase()}</Text>
          </View>
          <TextInput
            value={text}
            onChangeText={setText}
            multiline
            autoFocus
            placeholder="What is worth sharing?"
            placeholderTextColor={t.textMuted}
            style={styles.input}
            maxLength={MAX_POST_LENGTH}
            accessibilityLabel="Post text"
            textAlignVertical="top"
          />
        </View>
        <View style={styles.footer}>
          <View style={styles.policy}>
            <Ionicons name={audienceSafe ? 'checkmark-circle-outline' : 'alert-circle-outline'} size={17} color={audienceSafe ? t.positive : t.negative} />
            <Text variant="metadata" tone={audienceSafe ? 'muted' : 'negative'}>{audienceSafe ? 'General-audience text' : 'Explicit text is not supported'}</Text>
          </View>
          <Text variant="metadata" tone={text.length > 260 ? 'warning' : 'muted'} weight="700">{MAX_POST_LENGTH - text.length}</Text>
        </View>
        {status ? <Text variant="metadata" tone="negative" style={styles.error} accessibilityRole="alert">{status}</Text> : null}
      </View>
    </SafeAreaView>
  )
}

const makeStyles = (t: ThemeTokens) => StyleSheet.create({
  screen: { flex: 1, backgroundColor: t.bg },
  flex: { flex: 1 },
  busy: { width: 64, minHeight: 48, alignItems: 'center', justifyContent: 'center' },
  context: { minHeight: 44, paddingHorizontal: 12, flexDirection: 'row', gap: 7, alignItems: 'center', borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: t.border, backgroundColor: t.surface },
  editor: { flex: 1, minHeight: 190, paddingHorizontal: 12, paddingTop: 12, flexDirection: 'row', alignItems: 'flex-start', gap: 10 },
  identity: { width: 40, height: 40, borderRadius: 12, alignItems: 'center', justifyContent: 'center', backgroundColor: t.surfaceAlt, borderWidth: StyleSheet.hairlineWidth, borderColor: t.border },
  identityText: { color: t.textMuted },
  input: { flex: 1, minHeight: 180, color: t.text, fontSize: 17, lineHeight: 24, padding: 0 },
  footer: { minHeight: 52, paddingHorizontal: 12, flexDirection: 'row', alignItems: 'center', borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: t.border },
  policy: { flex: 1, minWidth: 0, flexDirection: 'row', gap: 6, alignItems: 'center' },
  error: { paddingHorizontal: 12, paddingVertical: 9, backgroundColor: t.negativeSoft },
})

import { Database } from 'bun:sqlite'
import { createHash, randomBytes } from 'node:crypto'

export function tokenHash(token: string): string { return createHash('sha256').update(token).digest('hex') }
export class AccessStore {
  readonly db: Database
  constructor(path: string) {
    this.db = new Database(path, { create: true })
    this.db.exec(`PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS tokens (hash TEXT PRIMARY KEY, label TEXT NOT NULL, expires INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS usage (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);`)
  }
  issue(label: string, days = 30): string {
    const token = randomBytes(32).toString('base64url')
    this.db.query('INSERT INTO tokens VALUES (?, ?, ?)').run(tokenHash(token), label, Date.now() + days * 86400000)
    return token
  }
  revoke(label: string): void { this.db.query('DELETE FROM tokens WHERE label = ?').run(label) }
  authenticate(token: string): string | null {
    if (!/^[\w-]{43}$/.test(token)) return null
    const hash = tokenHash(token)
    return this.db.query('SELECT hash FROM tokens WHERE hash = ? AND expires > ?').get(hash, Date.now()) ? hash : null
  }
  consume(identity: string, cost = 1): boolean {
    const now = Date.now()
    const limits: [string, number, number][] = [
      [`minute:${identity}:${Math.floor(now / 60000)}`, 30, 60000],
      [`day:${identity}:${Math.floor(now / 86400000)}`, 300, 86400000],
      [`global:${Math.floor(now / 86400000)}`, 3000, 86400000],
    ]
    return this.db.transaction(() => {
      this.db.query('DELETE FROM usage WHERE expires < ?').run(now)
      for (const [key, limit] of limits) {
        const row = this.db.query('SELECT count FROM usage WHERE key = ?').get(key) as { count: number } | null
        if ((row?.count ?? 0) + cost > limit) return false
      }
      for (const [key, , period] of limits) this.db.query('INSERT INTO usage VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET count = count + excluded.count').run(key, cost, now + period)
      return true
    }).immediate()
  }
}

import { useCallback, useEffect, useMemo, useRef, useState, type JSX } from 'react'
import { ActivityIndicator, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native'
import { SafeAreaView } from 'react-native-safe-area-context'
import { router, useLocalSearchParams } from 'expo-router'
import Ionicons from '@expo/vector-icons/Ionicons'

import { serviceHasWeb, useServiceConnected } from '@/engine/service/connection'
import { Button } from '@/ui/design/Button'
import { askFeedAgent, presentAgentText, type FeedAgentAnswer } from '@/engine/agent/feedAgent'
import { fetchNews } from '@/engine/news/feed'
import { getSource } from '@/engine/news/registry'
import type { NewsItem } from '@/engine/news/types'
import { researchTrustedWeb } from '@/engine/web/firecrawl'
import { PressableScale } from '@/ui/ios/PressableScale'
import { openLink } from '@/ui/openLink'
import { AppHeader } from '@/ui/shell/AppHeader'
import { useTheme, useThemedStyles, type ThemeTokens } from '@/ui/theme'

const STARTERS = [
  { icon: 'git-compare-outline' as const, label: 'Compare coverage', prompt: 'Where do Reuters and AP differ on [topic]?' },
  { icon: 'checkmark-done-outline' as const, label: 'Check a claim', prompt: 'Verify [claim] against two independent reports.' },
  { icon: 'reader-outline' as const, label: 'Build a brief', prompt: 'Brief me on [event], separating confirmed facts from open questions.' },
]

export default function ResearchScreen(): JSX.Element {
  const connected = useServiceConnected()
  const t = useTheme()
  const styles = useThemedStyles(makeStyles)
  const abort = useRef<AbortController | null>(null)
  const inputRef = useRef<TextInput>(null)
  const params = useLocalSearchParams<{ q?: string }>()
  const [query, setQuery] = useState(typeof params.q === 'string' ? params.q : '')
  const [loading, setLoading] = useState(false)
  const [answer, setAnswer] = useState<FeedAgentAnswer | null>(null)
  const [sources, setSources] = useState<NewsItem[]>([])
  const [error, setError] = useState<string | null>(null)
  const [credits, setCredits] = useState(0)
  const [groundingNote, setGroundingNote] = useState('')
  const presentation = useMemo(() => answer ? presentAgentText(answer.text) : null, [answer])

  useEffect(() => () => abort.current?.abort(), [])
  useEffect(() => {
    if (typeof params.q === 'string') {
      abort.current?.abort()
      setLoading(false)
      setQuery(params.q)
      setAnswer(null)
      setSources([])
      setError(null)
    }
  }, [params.q])

  const run = useCallback(async () => {
    const question = query.trim()
    if (!question || loading) return
    if (!connected) { router.push({ pathname: '/settings', params: { connect: '1' } }); return }
    abort.current?.abort()
    const controller = new AbortController()
    abort.current = controller
    setLoading(true)
    setError(null)
    setAnswer(null)
    setSources([])
    setCredits(0)
    setGroundingNote('')
    try {
      let context: NewsItem[] = []
      let note = ''
      let usedCredits = 0
      if (serviceHasWeb()) {
        try {
          const web = await researchTrustedWeb(question, controller.signal)
          context = web.items
          usedCredits = web.credits
          if (!context.length) note = 'No web matches; using current feed headlines.'
        } catch {
          if (controller.signal.aborted) return
          note = 'Web research unavailable; using current feed headlines.'
        }
      } else note = 'Based on current feed headlines; web research is not connected.'
      if (!context.length) {
        context = (await fetchNews('all', null)).filter((item) => getSource(item.sourceId)?.evidenceRole === 'editorial')
        const terms = question.toLowerCase().match(/[\p{L}\p{N}]{4,}/gu) ?? []
        const relevance = (item: NewsItem) => terms.reduce((n, word) => n + Number(`${item.title} ${item.hover ?? ''}`.toLowerCase().includes(word)), 0)
        context.sort((a, b) => relevance(b) - relevance(a))
      }
      if (controller.signal.aborted) return
      if (!context.length) throw new Error('No sources available. Refresh Today and try again.')
      setGroundingNote(note)
      setCredits(usedCredits)
      const result = await askFeedAgent(question, context, controller.signal)
      if (!result) throw new Error('Research is unavailable. Check your AI connection in Settings and try again.')
      if (controller.signal.aborted) return
      setSources(result.sources)
      setAnswer(result)
    } catch (runError) {
      if (!controller.signal.aborted) setError(runError instanceof Error ? runError.message : 'Research failed.')
    } finally {
      if (!controller.signal.aborted) setLoading(false)
    }
  }, [connected, loading, query])

  return (
    <SafeAreaView style={styles.screen} edges={['top', 'left', 'right']}>
      <AppHeader back={false} title="Ask" subtitle="Answers with sources" />
      <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled" keyboardDismissMode="on-drag">
        <View style={styles.command}>
          <Ionicons name="search-outline" size={18} color={t.textMuted} />
          <TextInput
            ref={inputRef}
            value={query}
            onChangeText={setQuery}
            onSubmitEditing={() => void run()}
            placeholder="Ask about the news"
            placeholderTextColor={t.textMuted}
            style={styles.input}
            returnKeyType="search"
            accessibilityLabel="Research question"
          />
          <PressableScale
            style={[styles.run, (!query.trim() || loading) && styles.disabled]}
            disabled={!query.trim() || loading}
            onPress={() => void run()}
            accessibilityRole="button"
            accessibilityLabel="Run research"
            accessibilityState={{ busy: loading, disabled: !query.trim() || loading }}
          >
            {loading ? <ActivityIndicator size="small" color={t.onAccent} /> : <Ionicons name="arrow-up" size={17} color={t.onAccent} />}
          </PressableScale>
        </View>
        {!connected ? <View style={styles.connect}><Text style={styles.connectionLabel}>AI not connected</Text><Button label="Connect" variant="ghost" onPress={() => router.push({ pathname: '/settings', params: { connect: '1' } })} /></View> : null}

        {error ? (
          <View style={styles.error} accessibilityRole="alert">
            <Ionicons name="alert-circle-outline" size={17} color={t.negative} />
            <View style={styles.errorCopy}>
              <Text style={styles.errorTitle}>Couldn’t finish research</Text>
              <Text style={styles.errorBody}>{error}</Text>
            </View>
          </View>
        ) : null}

        {!loading && !answer && !error && !sources.length ? (
          <View style={styles.starters}>
            <Text style={styles.section}>Try asking</Text>
            {STARTERS.map((item) => (
              <PressableScale
                key={item.label}
                style={styles.starter}
                haptic={false}
                onPress={() => { setQuery(item.prompt); inputRef.current?.focus() }}
                accessibilityRole="button"
                accessibilityLabel={`${item.label}: ${item.prompt}`}
              >
                <View style={styles.starterIcon}><Ionicons name={item.icon} size={17} color={t.accent} /></View>
                <View style={styles.starterCopy}>
                  <Text style={styles.starterLabel}>{item.label}</Text>
                </View>
                <Ionicons name="arrow-forward" size={15} color={t.textMuted} />
              </PressableScale>
            ))}
          </View>
        ) : null}

        {answer && presentation ? (
          <View style={styles.answer}>
            <View style={styles.answerTop}>
              <Text style={styles.answerLabel}>{presentation.heading}</Text>
              <Text style={styles.answerMeta}>{answer.providerLabel} · {(answer.elapsedMs / 1000).toFixed(1)}s · {credits} credits</Text>
            </View>
            {groundingNote ? <Text style={styles.groundingNote}>{groundingNote}</Text> : null}
            {presentation.highlights.length ? presentation.highlights.map((line, index) => (
              <View key={`${index}:${line}`} style={styles.bullet}>
                <View style={styles.dot} />
                <Text style={styles.answerText}>{line}</Text>
              </View>
            )) : <Text style={styles.answerText}>{presentation.prose}</Text>}
          </View>
        ) : null}

        {sources.length ? (
          <>
            <Text style={styles.section}>Verified sources · {sources.length}</Text>
            <View style={styles.sourceGroup}>
              {sources.map((source, index) => (
                <PressableScale
                  key={source.id}
                  style={styles.source}
                  onPress={() => openLink(source.url, source.title)}
                  accessibilityRole="link"
                  accessibilityLabel={`Source ${index + 1}: ${source.title}`}
                >
                  <Text style={styles.sourceNo}>[{index + 1}]</Text>
                  <View style={styles.sourceCopy}>
                    <Text style={styles.sourceTitle} numberOfLines={2}>{source.title}</Text>
                    <Text style={styles.sourceMeta}>{source.sourceId}</Text>
                  </View>
                  <Ionicons name="open-outline" size={16} color={t.textMuted} />
                </PressableScale>
              ))}
            </View>
          </>
        ) : null}
      </ScrollView>
    </SafeAreaView>
  )
}

const makeStyles = (t: ThemeTokens) => StyleSheet.create({
  screen: { flex: 1, backgroundColor: t.bg },
  content: { paddingBottom: 40, maxWidth: 720, width: '100%', alignSelf: 'center' },
  connectionLabel: { color: t.textMuted, fontSize: 13 },
  connect: { marginHorizontal: 16, flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },
  command: { marginHorizontal: 16, minHeight: 56, borderRadius: 16, backgroundColor: t.surface, paddingHorizontal: 8, flexDirection: 'row', gap: 8, alignItems: 'center', borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: t.border },
  input: { flex: 1, minWidth: 0, height: 48, color: t.text, fontSize: 14 },
  run: { width: 48, height: 48, borderRadius: 24, alignItems: 'center', justifyContent: 'center', backgroundColor: t.accent },
  disabled: { opacity: 0.4 },
  starters: { marginHorizontal: 16, marginTop: 16 },
  starter: { minHeight: 56, paddingHorizontal: 12, paddingVertical: 4, borderRadius: 12, marginBottom: 6, backgroundColor: t.surface, flexDirection: 'row', gap: 8, alignItems: 'center', borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: t.border },
  starterIcon: { width: 36, height: 48, alignItems: 'center', justifyContent: 'center' },
  starterCopy: { flex: 1, minWidth: 0 },
  starterLabel: { color: t.text, fontSize: 14, lineHeight: 24, fontWeight: '600' },
  error: { minHeight: 58, margin: 10, padding: 10, flexDirection: 'row', gap: 8, alignItems: 'flex-start', borderWidth: StyleSheet.hairlineWidth, borderColor: t.negative, borderRadius: 9, backgroundColor: t.negativeSoft },
  errorCopy: { flex: 1 },
  errorTitle: { color: t.negative, fontSize: 14, fontWeight: '600' },
  errorBody: { color: t.negative, fontSize: 12, lineHeight: 18, marginTop: 3 },
  answer: { margin: 16, padding: 16, borderWidth: StyleSheet.hairlineWidth, borderColor: t.border, borderRadius: 16, backgroundColor: t.surface },
  groundingNote: { color: t.textMuted, fontSize: 12, lineHeight: 18, marginVertical: 8 },
  answerTop: { minHeight: 30, flexDirection: 'row', gap: 8, alignItems: 'flex-start', justifyContent: 'space-between' },
  answerLabel: { flex: 1, color: t.text, fontSize: 14, fontWeight: '600' },
  answerMeta: { color: t.textMuted, fontSize: 12 },
  bullet: { flexDirection: 'row', marginTop: 6 },
  dot: { width: 4, height: 4, borderRadius: 2, backgroundColor: t.accent, marginTop: 6, marginRight: 8 },
  answerText: { flex: 1, color: t.text, fontSize: 14, lineHeight: 22 },
  section: { minHeight: 34, paddingHorizontal: 12, paddingTop: 12, paddingBottom: 5, color: t.textMuted, fontSize: 12, lineHeight: 18, fontWeight: '600' },
  sourceGroup: { borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: t.border },
  source: { minHeight: 64, paddingHorizontal: 16, flexDirection: 'row', gap: 7, alignItems: 'center', borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: t.border },
  sourceNo: { width: 28, color: t.accent, fontSize: 12, fontWeight: '600' },
  sourceCopy: { flex: 1, minWidth: 0 },
  sourceTitle: { color: t.text, fontSize: 14, lineHeight: 18, fontWeight: '700' },
  sourceMeta: { color: t.textMuted, fontSize: 12, lineHeight: 18, marginTop: 1 },
})

import { useEffect, useMemo, useRef, useState, type JSX } from 'react'
import { ActivityIndicator, Linking, StyleSheet, Text, View } from 'react-native'
import { router, useLocalSearchParams } from 'expo-router'
import { SafeAreaView } from 'react-native-safe-area-context'
import { WebView, type WebViewNavigation } from 'react-native-webview'
import Ionicons from '@expo/vector-icons/Ionicons'

import { claimTorWebViewProxy, releaseWebViewProxy, usePrivacySnapshot } from '@/engine/privacy'
import { PressableScale } from '@/ui/ios/PressableScale'
import { useTheme, useThemedStyles, type ThemeTokens } from '@/ui/theme'

const WEB_URL = /^https?:\/\//i
type BrowserRoute = 'direct' | 'connecting' | 'tor' | 'blocked'

export default function BrowserScreen(): JSX.Element {
  const params = useLocalSearchParams<{ url?: string; title?: string }>()
  const initialUrl = Array.isArray(params.url) ? params.url[0] : params.url
  const initialTitle = Array.isArray(params.title) ? params.title[0] : params.title
  const safeUrl = WEB_URL.test(initialUrl ?? '') ? initialUrl! : ''
  const privacy = usePrivacySnapshot()
  const theme = useTheme()
  const styles = useThemedStyles(makeStyles)
  const webRef = useRef<WebView>(null)
  const [currentUrl, setCurrentUrl] = useState(safeUrl)
  const [pageTitle, setPageTitle] = useState(initialTitle ?? '')
  const [loading, setLoading] = useState(true)
  const [routeState, setRouteState] = useState<BrowserRoute>(() => privacy.torEnabled ? 'connecting' : privacy.relayEnabled ? 'blocked' : 'direct')

  const host = useMemo(() => {
    try {
      return new URL(currentUrl || safeUrl).hostname.replace(/^www\./, '')
    } catch {
      return 'Article'
    }
  }, [currentUrl, safeUrl])
  const isX = host === 'x.com' || host.endsWith('.x.com') || host === 'twitter.com' || host.endsWith('.twitter.com')
  useEffect(() => {
    const owner = {}
    let live = true
    const configure = async () => {
      if (!privacy.torEnabled) {
        setRouteState(privacy.relayEnabled ? 'blocked' : 'direct')
        return
      }
      if (privacy.torStatus !== 'ON') {
        setRouteState(privacy.torStatus === 'STARTING' ? 'connecting' : 'blocked')
        return
      }
      setRouteState('connecting')
      const routed = await claimTorWebViewProxy(owner)
      if (!live) {
        if (routed) await releaseWebViewProxy(owner)
        return
      }
      setRouteState(routed ? 'tor' : 'blocked')
    }
    void configure()
    return () => {
      live = false
      void releaseWebViewProxy(owner)
    }
  }, [privacy.relayEnabled, privacy.torEnabled, privacy.torStatus])

  const onNavigation = (nav: WebViewNavigation) => {
    if (WEB_URL.test(nav.url)) {
      setCurrentUrl(nav.url)
    }
    if (!initialTitle && nav.title) setPageTitle(nav.title)
  }

  const routeReady = routeState === 'direct' || routeState === 'tor'
  if (!safeUrl || !routeReady) {
    const invalid = !safeUrl
    const connecting = !invalid && routeState === 'connecting'
    const relayOnly = !invalid && privacy.relayEnabled && !privacy.torEnabled
    const detail = invalid
      ? 'This article link is not valid.'
      : connecting
        ? 'Connecting this browser to embedded Tor. Direct loading stays blocked.'
        : relayOnly
          ? 'The relay protects feeds and media, but cannot cover every WebView subrequest. Turn on embedded Tor or Orbot VPN.'
          : 'Private WebView routing is unavailable. Tru blocked the page instead of loading it directly.'
    return (
      <SafeAreaView style={styles.container}>
        <View style={styles.empty}>
          <View style={styles.alertCircle}>{connecting ? <ActivityIndicator size="small" color={styles.alertGlyph.color} /> : <Ionicons name={invalid ? 'alert-outline' : 'shield-checkmark-outline'} size={20} color={styles.alertGlyph.color} />}</View>
          <Text style={styles.emptyText}>{detail}</Text>
          <PressableScale style={styles.doneButton} onPress={() => router.back()} accessibilityRole="button" accessibilityLabel="Go back">
            <Text style={styles.doneText}>Go back</Text>
          </PressableScale>
        </View>
      </SafeAreaView>
    )
  }

  return (
    <SafeAreaView style={styles.container} edges={['top', 'left', 'right', 'bottom']}>
      <View style={styles.header}>
        <PressableScale onPress={() => router.back()} hitSlop={10} style={styles.iconButton} accessibilityRole="button" accessibilityLabel="Close browser">
          <Text style={styles.backGlyph}>‹</Text>
        </PressableScale>
        <View style={styles.heading}>
          <Text style={styles.pageTitle} numberOfLines={1}>{pageTitle || host}</Text>
          <Text style={styles.host} numberOfLines={1}>{routeState === 'tor' ? `Tor · ${host}` : host}</Text>
        </View>
        {routeState === 'direct' ? <PressableScale
          onPress={() => void Linking.openURL(currentUrl || safeUrl).catch(() => {})}
          hitSlop={10}
          style={styles.iconButton}
          accessibilityRole="link"
          accessibilityLabel="Open in system browser"
        >
          <Text style={styles.openGlyph}>↗</Text>
        </PressableScale> : <View style={styles.iconButton} />}
      </View>
      <View style={styles.webWrap}>
        <WebView
          ref={webRef}
          source={{ uri: safeUrl }}
          style={styles.web}
          onLoadStart={() => setLoading(true)}
          onLoadEnd={() => setLoading(false)}
          onLoadProgress={({ nativeEvent }) => {
            // WebView can keep loading ads/images long after readable content is
            // painted. Stop obscuring the article once the main page is underway.
            if (nativeEvent.progress >= 0.25) setLoading(false)
          }}
          onNavigationStateChange={onNavigation}
          onShouldStartLoadWithRequest={(request) => {
            if (WEB_URL.test(request.url)) return true
            if (routeState === 'direct') void Linking.openURL(request.url).catch(() => {})
            return false
          }}
          javaScriptEnabled
          domStorageEnabled
          incognito={!isX}
          sharedCookiesEnabled={isX}
          thirdPartyCookiesEnabled={isX}
        />
        {loading ? (
          <View style={styles.loading} pointerEvents="none">
            <ActivityIndicator color={theme.accent} />
          </View>
        ) : null}
      </View>
    </SafeAreaView>
  )
}

