    defaultModel: 'nvidia/nemotron-3-super-120b-a12b',



  },
]

const TIER_ORDER: Record<LlmTier, LlmProviderId[]> = {
  fast: ['nvidia', 'cerebras', 'groq', 'openrouter', 'gemini'],
  long: ['gemini', 'openrouter', 'cerebras', 'groq', 'nvidia'],
  variety: ['openrouter', 'gemini', 'cerebras', 'nvidia', 'groq'],
}

function resolve(definition: ProviderDefinition): LlmProvider {
  return {
    id: definition.id,
    label: definition.label,
    baseUrl: definition.defaultBaseUrl.replace(/\/+$/, ''),
    key: '',
    model: definition.defaultModel.trim(),
    disabled: false,
  }
}

export function allProviders(): (LlmProvider & { hasKey: boolean })[] {
  return DEFINITIONS.map(resolve).map((provider) => ({ ...provider, hasKey: serviceHasProvider(provider.id) }))
}

export function providerById(id: LlmProviderId): LlmProvider | null {
  const definition = DEFINITIONS.find((candidate) => candidate.id === id)
  return definition ? resolve(definition) : null
}

export function configuredProviders(tier: LlmTier = 'fast'): LlmProvider[] {
  const rank = TIER_ORDER[tier]
  return allProviders()
    .filter((provider) => provider.hasKey && !provider.disabled && provider.baseUrl && provider.model)
    .sort((a, b) => rank.indexOf(a.id) - rank.indexOf(b.id))
}

export function llmConfigured(): boolean {
  return configuredProviders().length > 0
}

import {
  configuredProviders,
  providerById,
  type LlmProvider,
  type LlmProviderId,
  type LlmTier,
} from './providers'
import { serviceFetch, serviceHasProvider } from '../service/connection'

export interface LlmMessage {
  role: 'system' | 'user' | 'assistant'
  content: string
}

export interface LlmOptions {
  maxTokens?: number
  temperature?: number
  timeoutMs?: number
  tier?: LlmTier
  signal?: AbortSignal
}

export interface LlmResult {
  text: string
  providerId: LlmProviderId
  providerLabel: string
  elapsedMs: number
}

export interface ProviderTestResult {
  ok: boolean
  elapsedMs: number
  detail: string
}

interface ChatResponse {
  choices?: { message?: { content?: string } }[]
  error?: { message?: string }
}

function statusHint(status: number): string {
  if (status === 401 || status === 403) return ': key rejected or missing permission'
  if (status === 402) return ': account credits or billing required'
  if (status === 404) return ': model or endpoint unavailable'
  if (status === 429) return ': rate limit reached'
  return ''
}

async function callProvider(provider: LlmProvider, messages: LlmMessage[], options: LlmOptions): Promise<string> {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? 25_000)
  const abort = () => controller.abort()
  options.signal?.addEventListener('abort', abort)
  try {
    const response = await serviceFetch(`/v1/chat/${provider.id}`, {
      messages, max_tokens: options.maxTokens ?? 900,
    }, controller.signal)
    if (!response.ok) {
      let detail = ''
      try {
        const body = (await response.json()) as ChatResponse
        if (body.error?.message) detail = `: ${body.error.message.slice(0, 120)}`
      } catch {
        // Status still provides a useful failure reason.
      }
      throw new Error(`HTTP ${response.status}${detail || statusHint(response.status)}`)
    }
    const body = (await response.json()) as ChatResponse
    const text = body.choices?.[0]?.message?.content?.trim()
    if (!text) throw new Error('Empty response')
    return text
  } finally {
    clearTimeout(timer)
    options.signal?.removeEventListener('abort', abort)
  }
}

export async function llmChat(messages: LlmMessage[], options: LlmOptions = {}): Promise<LlmResult | null> {
  for (const provider of configuredProviders(options.tier)) {
    if (options.signal?.aborted) return null
    const startedAt = Date.now()
    try {
      const text = await callProvider(provider, messages, options)
      return {
        text,
        providerId: provider.id,
        providerLabel: provider.label,
        elapsedMs: Date.now() - startedAt,
      }
    } catch (error) {
      console.warn(`[agent] ${provider.id} failed: ${(error as Error)?.message ?? 'request failed'}`)
    }
  }
  return null
}

export async function testProvider(id: LlmProviderId): Promise<ProviderTestResult> {
  const provider = providerById(id)
  if (!provider) return { ok: false, elapsedMs: 0, detail: 'Unknown provider' }
  if (!serviceHasProvider(id)) return { ok: false, elapsedMs: 0, detail: 'Connect Tru service in Settings.' }
  const startedAt = Date.now()
  try {
    const text = await callProvider(
      provider,
      [{ role: 'user', content: 'Reply with the single word: ok' }],
      { maxTokens: 200, temperature: 0, timeoutMs: 40_000 },
    )
    return { ok: true, elapsedMs: Date.now() - startedAt, detail: text.slice(0, 48) }
  } catch (error) {
    return {
      ok: false,
      elapsedMs: Date.now() - startedAt,
      detail: (error as Error)?.message ?? 'Request failed',
    }
  }
}

import { trustedPublisherForUrl, trustedSearchDomains } from '../news/registry'
import { isGeneralAudienceNews } from '../news/safety'
import { serviceFetch, serviceHasWeb } from '../service/connection'
import type { EvidenceRole, NewsItem } from '../news/types'

type SecureStoreModule = typeof import('expo-secure-store')

const API_BASE = 'https://api.firecrawl.dev/v2'
const STORAGE_KEY = 'tru.firecrawl.usage.v1'
const REQUEST_TIMEOUT_MS = 20_000

/** A deliberate device-side guardrail below Firecrawl's advertised free allocation. */
export const FIRECRAWL_DAILY_CREDIT_LIMIT = 40
export const FIRECRAWL_MONTHLY_CREDIT_LIMIT = 400
export const FIRECRAWL_SEARCH_CREDITS = 2
export const FIRECRAWL_SCRAPE_CREDITS = 1

interface UsageLedger {
  day: string
  dayCredits: number
  month: string
  monthCredits: number
}

export interface FirecrawlUsage {
  dayCredits: number
  dailyLimit: number
  monthCredits: number
  monthlyLimit: number
  mode: 'disconnected' | 'service'
  availability: 'untested' | 'available' | 'unavailable'
  detail?: string
}

export interface TrustedWebResult {
  id: string
  publisherId: string
  publisher: string
  short: string
  role: EvidenceRole
  title: string
  description?: string
  url: string
  position?: number
}

export interface FirecrawlSearchResult {
  results: TrustedWebResult[]
  usage: FirecrawlUsage
  credits: number
}

export type FirecrawlErrorCode = 'quota' | 'rate-limit' | 'network-blocked' | 'request' | 'invalid-response'

export class FirecrawlError extends Error {
  constructor(public readonly code: FirecrawlErrorCode, message: string) {
    super(message)
    this.name = 'FirecrawlError'
  }
}

let ledger: UsageLedger | null = null
let quotaQueue: Promise<unknown> = Promise.resolve()
let availability: FirecrawlUsage['availability'] = 'untested'
let availabilityDetail: string | undefined

function secureStore(): SecureStoreModule | null {
  try {
    return require('expo-secure-store') as SecureStoreModule
  } catch {
    return null
  }
}

function periodKeys(now = Date.now()): { day: string; month: string } {
  const iso = new Date(now).toISOString()
  return { day: iso.slice(0, 10), month: iso.slice(0, 7) }
}

export function normalizeFirecrawlLedger(value: unknown, now = Date.now()): UsageLedger {
  const periods = periodKeys(now)
  const candidate = value && typeof value === 'object' ? value as Partial<UsageLedger> : {}
  return {
    day: periods.day,
    dayCredits: candidate.day === periods.day && Number.isFinite(candidate.dayCredits)
      ? Math.max(0, Math.floor(candidate.dayCredits ?? 0))
      : 0,
    month: periods.month,
    monthCredits: candidate.month === periods.month && Number.isFinite(candidate.monthCredits)
      ? Math.max(0, Math.floor(candidate.monthCredits ?? 0))
      : 0,
  }
}

async function loadLedger(): Promise<UsageLedger> {
  if (ledger) {
    ledger = normalizeFirecrawlLedger(ledger)
    return ledger
  }
  try {
    const raw = await secureStore()?.getItemAsync(STORAGE_KEY)
    ledger = normalizeFirecrawlLedger(raw ? JSON.parse(raw) : null)
  } catch {
    ledger = normalizeFirecrawlLedger(null)
  }
  return ledger
}

function usageFromLedger(current: UsageLedger): FirecrawlUsage {
  return {
    dayCredits: current.dayCredits,
    dailyLimit: FIRECRAWL_DAILY_CREDIT_LIMIT,
    monthCredits: current.monthCredits,
    monthlyLimit: FIRECRAWL_MONTHLY_CREDIT_LIMIT,
    mode: serviceHasWeb() ? 'service' : 'disconnected',
    availability,
    detail: availabilityDetail,
  }
}

function withQuotaLock<T>(operation: () => Promise<T>): Promise<T> {
  const result = quotaQueue.then(operation, operation)
  quotaQueue = result.then(() => undefined, () => undefined)
  return result
}

export function getFirecrawlUsage(): Promise<FirecrawlUsage> {
  return withQuotaLock(async () => usageFromLedger(await loadLedger()))
}

async function reserveCredits(cost: number): Promise<FirecrawlUsage> {
  return withQuotaLock(async () => {
    const current = await loadLedger()
    if (current.dayCredits + cost > FIRECRAWL_DAILY_CREDIT_LIMIT) {
      throw new FirecrawlError('quota', 'Tru’s daily web allowance is used. Direct feeds and saved stories still work.')
    }
    if (current.monthCredits + cost > FIRECRAWL_MONTHLY_CREDIT_LIMIT) {
      throw new FirecrawlError('quota', 'Tru’s monthly web allowance is used. Direct feeds and saved stories still work.')
    }
    ledger = {
      ...current,
      dayCredits: current.dayCredits + cost,
      monthCredits: current.monthCredits + cost,
    }
    try {
      await secureStore()?.setItemAsync(STORAGE_KEY, JSON.stringify(ledger))
    } catch {
      // The in-memory guardrail remains active for this app session.
    }
    return usageFromLedger(ledger)
  })
}

async function releaseCredits(cost: number): Promise<void> {
  await withQuotaLock(async () => {
    const current = await loadLedger()
    ledger = {
      ...current,
      dayCredits: Math.max(0, current.dayCredits - cost),
      monthCredits: Math.max(0, current.monthCredits - cost),
    }
    try {
      await secureStore()?.setItemAsync(STORAGE_KEY, JSON.stringify(ledger))
    } catch {
      // The in-memory counter is still corrected.
    }
  })
}

function readableApiError(status: number, detail: string): FirecrawlError {
  if (/suspicious|without an api key/i.test(detail)) {
    return new FirecrawlError(
      'network-blocked',
      'Web research is unavailable on this service. Direct sources still work.',
    )
  }
  if (status === 429) {
    return new FirecrawlError(
      'rate-limit',
      'The web service allowance is currently exhausted. Direct sources still work.',
    )
  }
  return new FirecrawlError('request', detail || `Firecrawl request failed (${status}).`)
}

async function postFirecrawl(path: string, body: object, signal?: AbortSignal): Promise<unknown> {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS)
  const abort = () => controller.abort()
  signal?.addEventListener('abort', abort, { once: true })
  try {
    const response = await serviceFetch(`/v1/web${path}`, body, controller.signal)
    const raw = await response.text()
    let parsed: unknown
    try {
      parsed = raw ? JSON.parse(raw) : null
    } catch {
      throw new FirecrawlError('invalid-response', 'Firecrawl returned an unreadable response.')
    }
    const record = parsed && typeof parsed === 'object' ? parsed as Record<string, unknown> : null
    if (!response.ok || record?.success !== true) {
      const detail = typeof record?.error === 'string' ? record.error : ''
      availability = 'unavailable'
      const apiError = readableApiError(response.status, detail)
      availabilityDetail = apiError.message
      throw apiError
    }
    availability = 'available'
    availabilityDetail = undefined
    return parsed
  } catch (error) {
    if (error instanceof FirecrawlError) throw error
    if (signal?.aborted) throw error
    if (controller.signal.aborted) {
      availability = 'unavailable'
      availabilityDetail = 'Firecrawl did not respond in time. Direct Tru sources still work.'
      throw new FirecrawlError('request', availabilityDetail)
    }
    availability = 'unavailable'
    availabilityDetail = 'Firecrawl could not be reached. Direct Tru sources still work.'
    throw new FirecrawlError('request', availabilityDetail)
  } finally {
    clearTimeout(timeout)
    signal?.removeEventListener('abort', abort)
  }
}

function stableId(url: string): string {
  let hash = 2166136261
  for (let index = 0; index < url.length; index += 1) {
    hash ^= url.charCodeAt(index)
    hash = Math.imul(hash, 16777619)
  }
  return (hash >>> 0).toString(36)
}

function cleanText(value: unknown, maxLength: number): string | undefined {
  if (typeof value !== 'string') return undefined
  const clean = value.replace(/\s+/g, ' ').trim()
  return clean ? clean.slice(0, maxLength) : undefined
}

function parseSearchResults(payload: unknown): TrustedWebResult[] {
  const root = payload && typeof payload === 'object' ? payload as Record<string, unknown> : {}
  const data = root.data && typeof root.data === 'object' ? root.data as Record<string, unknown> : {}
  const web = Array.isArray(data.web) ? data.web : []
  const seen = new Set<string>()
  const results: TrustedWebResult[] = []

  for (const entry of web) {
    if (!entry || typeof entry !== 'object') continue
    const record = entry as Record<string, unknown>
    const url = typeof record.url === 'string' ? record.url : ''
    const title = cleanText(record.title, 300)
    const publisher = trustedPublisherForUrl(url)
    if (!publisher || !title || seen.has(url)) continue
    const candidate: TrustedWebResult = {
      id: `firecrawl:${stableId(url)}`,
      publisherId: publisher.id,
      publisher: publisher.name,
      short: publisher.short,
      role: publisher.evidenceRole,
      title,
      description: cleanText(record.description ?? record.snippet, 1_600),
      url,
      position: typeof record.position === 'number' ? record.position : undefined,
    }
    if (!isGeneralAudienceNews(trustedWebResultToNewsItem(candidate))) continue
    seen.add(url)
    results.push(candidate)
  }
  return results
}

export async function searchTrustedWeb(
  query: string,
  options: { limit?: number; recency?: 'day' | 'week' | 'month'; signal?: AbortSignal } = {},
): Promise<FirecrawlSearchResult> {
  const normalizedQuery = query.replace(/\s+/g, ' ').trim().slice(0, 320)
  if (!normalizedQuery) throw new FirecrawlError('request', 'A search query is required.')
  const limit = Math.min(10, Math.max(1, Math.floor(options.limit ?? 8)))
  const cost = Math.ceil(limit / 10) * FIRECRAWL_SEARCH_CREDITS
  const usage = await reserveCredits(cost)
  const recency = options.recency ?? 'week'
  const tbs = recency === 'day' ? 'qdr:d' : recency === 'month' ? 'qdr:m' : 'qdr:w'
  let payload: unknown
  try {
    payload = await postFirecrawl('/search', {
      query: normalizedQuery,
      limit,
      sources: ['web'],
      includeDomains: trustedSearchDomains(),
      tbs,
      safe: true,
      highlights: false,
      timeout: 15_000,
    }, options.signal)
  } catch (error) {
    await releaseCredits(cost)
    throw error
  }
  return { results: parseSearchResults(payload), usage, credits: cost }
}

function markdownExcerpt(markdown: string): string | undefined {
  return cleanText(
    markdown
      .replace(/!\[[^\]]*]\([^)]*\)/g, ' ')
      .replace(/\[([^\]]+)]\([^)]*\)/g, '$1')
      .replace(/[`#>*_|~]+/g, ' '),
    1_800,
  )
}

export async function scrapeTrustedPage(url: string, signal?: AbortSignal): Promise<string | undefined> {
  if (!trustedPublisherForUrl(url)) {
    throw new FirecrawlError('request', 'Tru only extracts pages from its pinned publisher domains.')
  }
  await reserveCredits(FIRECRAWL_SCRAPE_CREDITS)
  let payload: unknown
  try {
    payload = await postFirecrawl('/scrape', {
      url,
      formats: ['markdown'],
      onlyMainContent: true,
      parsers: [],
      maxAge: 600_000,
      timeout: 15_000,
    }, signal)
  } catch (error) {
    await releaseCredits(FIRECRAWL_SCRAPE_CREDITS)
    throw error
  }
  const root = payload && typeof payload === 'object' ? payload as Record<string, unknown> : {}
  const data = root.data && typeof root.data === 'object' ? root.data as Record<string, unknown> : {}
  return typeof data.markdown === 'string' ? markdownExcerpt(data.markdown) : undefined
}

export function trustedWebResultToNewsItem(result: TrustedWebResult, excerpt?: string): NewsItem {
  return {
    id: result.id,
    sourceId: result.publisherId,
    title: result.title,
    url: result.url,
    hover: excerpt ?? result.description,
  }
}

export async function researchTrustedWeb(
  query: string,
  signal?: AbortSignal,
): Promise<{ items: NewsItem[]; credits: number; usage: FirecrawlUsage }> {
  const search = await searchTrustedWeb(query, { limit: 8, recency: 'week', signal })
  const selected = search.results.slice(0, 2)
  const scrapes = await Promise.all(selected.map(async (result) => {
    try {
      return { excerpt: await scrapeTrustedPage(result.url, signal), charged: true }
    } catch (error) {
      if (signal?.aborted) throw error
      return { excerpt: undefined, charged: false }
    }
  }))
  const items = search.results.map((result, index) =>
    trustedWebResultToNewsItem(result, index < scrapes.length ? scrapes[index]?.excerpt : undefined),
  )
  return {
    items,
    credits: search.credits + scrapes.filter((scrape) => scrape.charged).length * FIRECRAWL_SCRAPE_CREDITS,
    usage: await getFirecrawlUsage(),
  }
}

// Hacker News API client (Firebase v0, no auth).
//
// Responsibilities:
//  - fetch the story-id arrays per StoryType (cached with a short TTL)
//  - hydrate item ids into normalized `Story` rows in bounded-concurrency batches
//    (a story feed is ~500 ids; we only ever hydrate the visible slice)
//  - decode the HTML that HN returns in comment / Ask-HN `text`
//
// Caching is in-memory only so HN stays self-sufficient (a persisted cache
// helper may land under src/engine/cache/ later, but we don't depend on it).

import { isGeneralAudienceText } from '../news/safety'
import { privacyFetch } from '../privacy/transport'
import type { Comment, RawItem, Story, StoryType } from './types'
import { STORY_TYPES } from './types'

const BASE = 'https://hacker-news.firebaseio.com/v0'

// ---- caches ----------------------------------------------------------------

// Story-id arrays per feed, with a timestamp so we can re-pull periodically.
const idListCache = new Map<StoryType, { ids: number[]; at: number }>()
const ID_LIST_TTL = 60_000 // 1 min; the front page moves slowly

// Individual hydrated items, keyed by id. Shared across stories + comments so a
// comment fetched here is reused by the thread loader and vice-versa.
const itemCache = new Map<number, RawItem>()

function endpointFor(type: StoryType): string {
  const meta = STORY_TYPES.find((s) => s.key === type)
  return meta ? meta.endpoint : 'topstories'
}

// ---- low-level fetch --------------------------------------------------------

async function getJson<T>(url: string, signal?: AbortSignal): Promise<T> {
  const res = await privacyFetch(url, { signal })
  if (!res.ok) throw new Error(`HN ${res.status} ${url}`)
  return (await res.json()) as T
}

/** Fetch (and cache) a single raw item. Deduped by the item cache. */
export async function fetchItem(id: number, signal?: AbortSignal): Promise<RawItem | null> {
  const cached = itemCache.get(id)
  if (cached) return cached
  const item = await getJson<RawItem | null>(`${BASE}/item/${id}.json`, signal)
  if (item) itemCache.set(id, item)
  return item
}

/** Get the ordered id array for a feed, cached for ID_LIST_TTL. */
export async function fetchStoryIds(type: StoryType, fresh = false): Promise<number[]> {
  const cached = idListCache.get(type)
  if (!fresh && cached && Date.now() - cached.at < ID_LIST_TTL) return cached.ids
  const ids = await getJson<number[]>(`${BASE}/${endpointFor(type)}.json`)
  idListCache.set(type, { ids: ids ?? [], at: Date.now() })
  return ids ?? []
}

// ---- bounded-concurrency map ------------------------------------------------

/**
 * Run `worker` over `items` with at most `limit` in flight at once. Preserves
 * input order in the result. Keeps a fat id-list from opening 500 sockets.
 */
export async function mapPool<T, R>(
  items: T[],
  limit: number,
  worker: (item: T, index: number) => Promise<R>
): Promise<R[]> {
  const out: R[] = new Array(items.length)
  let next = 0
  const runners = new Array(Math.min(limit, items.length)).fill(0).map(async () => {
    while (true) {
      const i = next++
      if (i >= items.length) break
      out[i] = await worker(items[i], i)
    }
  })
  await Promise.all(runners)
  return out
}

// ---- normalization ----------------------------------------------------------

function domainOf(url?: string): string | undefined {
  if (!url) return undefined
  try {
    const host = new URL(url).hostname
    return host.replace(/^www\./, '')
  } catch {
    return undefined
  }
}

export function toStory(item: RawItem): Story {
  return {
    id: item.id,
    type: item.type,
    title: item.title ?? '(untitled)',
    url: item.url,
    domain: domainOf(item.url),
    by: item.by ?? 'unknown',
    time: item.time ?? 0,
    score: item.score ?? 0,
    commentCount: item.descendants ?? 0,
    text: item.text ? decodeHtml(item.text) : undefined,
    kids: item.kids ?? [],
  }
}

/**
 * Hydrate one page of stories: slice `ids[offset .. offset+limit]`, fetch the
 * items with bounded concurrency, drop dead/deleted, and normalize. Returns the
 * rows plus the next offset for infinite scroll.
 */
export async function fetchStoryPage(
  type: StoryType,
  offset: number,
  pageSize: number,
  fresh = false
): Promise<{ stories: Story[]; nextOffset: number; total: number }> {
  const ids = await fetchStoryIds(type, fresh && offset === 0)
  const slice = ids.slice(offset, offset + pageSize)
  const items = await mapPool(slice, 8, (id) => fetchItem(id))
  const stories = items
    .filter((it): it is RawItem => !!it && !it.dead && !it.deleted)
    .map(toStory)
  return { stories, nextOffset: offset + slice.length, total: ids.length }
}

// ---- HTML decoding ----------------------------------------------------------

const ENTITIES: Record<string, string> = {
  '&amp;': '&',
  '&lt;': '<',
  '&gt;': '>',
  '&quot;': '"',
  '&#x27;': "'",
  '&#x2F;': '/',
  '&#47;': '/',
  '&apos;': "'",
  '&nbsp;': ' ',
}

/**
 * HN comment/Ask `text` is a small HTML subset: `<p>` paragraph breaks, `<i>`,
 * `<a href>` links, `<pre><code>` blocks, and numeric/named entities. We render
 * as plain text, so: turn `<p>` into blank lines, strip other tags (keeping the
 * link href text), and decode entities. Newlines are preserved for the UI.
 */
export function decodeHtml(html: string): string {
  let s = html
  // Paragraph breaks -> double newline.
  s = s.replace(/<p>/gi, '\n\n')
  // Keep the visible href for anchors when it differs from the label; simplest
  // correct-enough approach is to just drop the tags and keep inner text.
  s = s.replace(/<a\b[^>]*>/gi, '').replace(/<\/a>/gi, '')
  // Preserve code/pre newlines, then strip the tags.
  s = s.replace(/<\/?(pre|code)>/gi, '')
  // Drop any remaining tags (<i>, <b>, etc.).
  s = s.replace(/<[^>]+>/g, '')
  // Decode named entities.
  s = s.replace(/&[a-z]+;|&#x?[0-9a-f]+;/gi, (m) => {
    const named = ENTITIES[m.toLowerCase()]
    if (named) return named
    const hex = /^&#x([0-9a-f]+);$/i.exec(m)
    if (hex) return safeCodePoint(parseInt(hex[1], 16))
    const dec = /^&#([0-9]+);$/.exec(m)
    if (dec) return safeCodePoint(parseInt(dec[1], 10))
    return m
  })
  return s.replace(/\n{3,}/g, '\n\n').trim()
}

function safeCodePoint(code: number): string {
  try {
    return String.fromCodePoint(code)
  } catch {
    return ''
  }
}

/** Test hook / cache reset (used by refresh). */
export function clearHnCache(): void {
  idListCache.clear()
  itemCache.clear()
}

/** Bounded breadth-first thread hydration; dead and explicit rows never reach UI. */
export async function fetchThread(storyId: number, maxComments = 50): Promise<{ story: Story; comments: Comment[] }> {
  const rawStory = await fetchItem(storyId)
  if (!rawStory) throw new Error('HN story not found.')
  const story = toStory(rawStory)
  const queue = [...story.kids]
  const rawComments = new Map<number, RawItem>()
  while (queue.length && rawComments.size < maxComments) {
    const batch = queue.splice(0, Math.min(10, maxComments - rawComments.size))
    const rows = await mapPool(batch, 6, (id) => fetchItem(id))
    for (const row of rows) {
      if (!row || row.dead || row.deleted || row.type !== 'comment') continue
      const text = decodeHtml(row.text ?? '')
      if (!text || !isGeneralAudienceText(text)) continue
      rawComments.set(row.id, { ...row, text })
      queue.push(...(row.kids ?? []))
    }
  }
  const build = (id: number, depth: number): Comment | null => {
    const row = rawComments.get(id)
    if (!row) return null
    return {
      id: row.id,
      by: row.by ?? 'unknown',
      time: row.time ?? 0,
      text: row.text ?? '',
      kids: row.kids ?? [],
      depth,
      replies: (row.kids ?? []).map((child) => build(child, depth + 1)).filter((value): value is Comment => Boolean(value)),
    }
  }
  return { story, comments: story.kids.map((id) => build(id, 0)).filter((value): value is Comment => Boolean(value)) }
}

