import { test, expect } from 'bun:test'
import worker from '../relay-worker/worker.js'
const env = { RATE_LIMITER: { limit: async () => ({ success: true }) } }
const request = (url: string) => new Request('https://relay.example/?url=' + encodeURIComponent(url))
test('relay requires its limiter and rejects arbitrary/private/credential URLs', async () => {
  expect((await worker.fetch(request('https://pbs.twimg.com/a'))).status).toBe(503)
  for (const target of ['https://evil.example', 'https://127.0.0.1', 'https://pbs.twimg.com.evil.example/a','https://user:pass@pbs.twimg.com/a','https://pbs.twimg.com:8443/a']) expect((await worker.fetch(request(target), env)).status).toBe(400)
  expect((await worker.fetch(request('https://pbs.twimg.com/a'), { RATE_LIMITER: { limit: async () => ({ success: false }) } })).status).toBe(429)
})
test('relay rejects redirect escapes, oversized responses, and strips cookies', async () => {
  const original = globalThis.fetch
  try {
    globalThis.fetch = (async () => new Response(null, { status: 302, headers: { location: 'https://evil.example' } })) as unknown as typeof fetch
    expect((await worker.fetch(request('https://pbs.twimg.com/a'), env)).status).toBe(502)
    globalThis.fetch = (async () => new Response('large', { headers: { 'content-length': '9000000' } })) as unknown as typeof fetch
    expect((await worker.fetch(request('https://pbs.twimg.com/a'), env)).status).toBe(502)
    globalThis.fetch = (async (_url, init) => {
      expect(new Headers(init?.headers).get('cookie')).toBeNull()
      return new Response('image', { headers: { 'set-cookie': 'secret=fixture', 'content-type': 'image/png' } })
    }) as typeof fetch
    const response = await worker.fetch(request('https://pbs.twimg.com/a'), env)
    expect(response.headers.get('set-cookie')).toBeNull()
    expect(await response.text()).toBe('image')
  } finally { globalThis.fetch = original }
})

import { test, expect } from 'bun:test'
import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { Database } from 'bun:sqlite'

test('issuing access twice never creates an undeliverable extra token', () => {
  const dir = mkdtempSync(join(tmpdir(), 'tru-access-test-'))
  const env = { ...process.env, TRU_DATA_DIR: dir }
  try {
    const issued = Bun.spawnSync([process.execPath, 'server/access.ts', 'issue', 'fixture'], { cwd: process.cwd(), env })
    expect(issued.exitCode).toBe(0)
    const token = readFileSync(join(dir, 'fixture.token'), 'utf8')
    const duplicate = Bun.spawnSync([process.execPath, 'server/access.ts', 'issue', 'fixture'], { cwd: process.cwd(), env })
    expect(duplicate.exitCode).not.toBe(0)
    expect(readFileSync(join(dir, 'fixture.token'), 'utf8')).toBe(token)
    const db = new Database(join(dir, 'access.sqlite'))
    expect(db.query('SELECT COUNT(*) AS count FROM tokens').get()).toEqual({ count: 1 })
    db.close()
    expect(Bun.spawnSync([process.execPath, 'server/access.ts', 'revoke', 'fixture'], { cwd: process.cwd(), env }).exitCode).toBe(0)
  } finally { rmSync(dir, { recursive: true, force: true }) }
})

import { test, expect } from 'bun:test'
import { readStoredSession, revokeStoredSession, SESSION_KEY, LEGACY_SESSION_KEY } from '../src/engine/x/sessionStorage'
test('migrated login stays signed out after restart', async () => {
  const data = new Map([[LEGACY_SESSION_KEY, '{"authToken":"fixture"}']])
  const store = { getItemAsync: async (k: string) => data.get(k) ?? null, setItemAsync: async (k: string, v: string) => { data.set(k,v) }, deleteItemAsync: async (k: string) => { data.delete(k) } }
  expect(await readStoredSession(store)).toContain('fixture')
  expect(data.has(LEGACY_SESSION_KEY)).toBe(false)
  await revokeStoredSession(store)
  expect(await readStoredSession(store)).toBeNull()
})
test('partial logout failure persists a tombstone that prevents old session recovery', async () => {
  const data = new Map([[LEGACY_SESSION_KEY, 'old']])
  const store = { getItemAsync: async (k: string) => data.get(k) ?? null, setItemAsync: async (k: string,v: string) => { data.set(k,v) }, deleteItemAsync: async () => { throw new Error('disk failure') } }
  await expect(revokeStoredSession(store)).rejects.toThrow()
  expect(data.get(SESSION_KEY)).toBe('null')
  expect(await readStoredSession(store)).toBe('null')
})
